-- changeset uakyol:37 dbms:cloudspanner
-- comment: Add EventGroup hierarchies, derived entity paths, and entity metadata search.

-- Set protobuf FileDescriptorSet as a base64 string. This gets applied to the next DDL batch.
SET PROTO_DESCRIPTORS = '';

START BATCH DDL;

ALTER PROTO BUNDLE INSERT (
  `wfa.measurement.internal.kingdom.EventGroupHierarchyDetails`,
  `wfa.measurement.internal.kingdom.EventGroupHierarchyDetails.Level`,
);

-- An ordered nesting of entity types for a DataProvider's EventGroups. Supplied
-- by operator configuration and applied by EventGroupHierarchyActivationJob.
CREATE TABLE EventGroupHierarchies (
  DataProviderId INT64 NOT NULL,
  EventGroupHierarchyId INT64 NOT NULL,

  -- The configuration-supplied resource ID, e.g. "dv360". Follows
  -- https://google.aip.dev/122#resource-id-segments.
  ExternalEventGroupHierarchyId STRING(63) NOT NULL,

  -- org.wfanet.measurement.internal.kingdom.EventGroupHierarchy.State
  -- protobuf enum encoded as an integer. PENDING while paths and ancestors are
  -- being derived; ACTIVE once complete. A PENDING EventGroupHierarchy is not
  -- served.
  State INT64 NOT NULL,

  EventGroupHierarchyDetails `wfa.measurement.internal.kingdom.EventGroupHierarchyDetails`
    NOT NULL,

  CreateTime TIMESTAMP NOT NULL OPTIONS (allow_commit_timestamp = true),
  UpdateTime TIMESTAMP OPTIONS (allow_commit_timestamp = true),
) PRIMARY KEY(DataProviderId, EventGroupHierarchyId),
  INTERLEAVE IN PARENT DataProviders ON DELETE CASCADE;

CREATE UNIQUE INDEX EventGroupHierarchiesByExternalId
  ON EventGroupHierarchies(DataProviderId, ExternalEventGroupHierarchyId);

-- True for a DataProvider-registered EventGroup, false for an ancestor derived
-- from a descendant's EntityMetadata. The default means existing rows need no
-- backfill.
ALTER TABLE EventGroups
  ADD COLUMN IsLeaf BOOL NOT NULL DEFAULT (TRUE);

-- Path from the root of the EventGroup's hierarchy to the EventGroup,
-- inclusive, as alternating entity type and ID segments with a trailing
-- delimiter, e.g. "dv360-campaign/X/dv360-line-item/L1/". Derived from
-- EntityMetadata. NULL for an EventGroup outside any hierarchy.
--
-- The trailing delimiter is required: without it, "dv360-campaign/X" is also a
-- string prefix of "dv360-campaign/X2/...". EntityType and the value of a
-- hierarchy level's id_entity_metadata_key are both URL-safe, so neither can
-- contain "/".
ALTER TABLE EventGroups
  ADD COLUMN EntityPath STRING(MAX);

-- The keys and scalar values of EntityMetadata, flattened by the service layer
-- for full-text search. This cannot be a generated column: EntityMetadata is a
-- google.protobuf.Struct, and GoogleSQL cannot enumerate its map entries.
ALTER TABLE EventGroups
  ADD COLUMN EntityMetadataText STRING(MAX);

ALTER TABLE EventGroups
  ADD COLUMN EntityMetadata_Tokens TOKENLIST AS (
    TOKENIZE_FULLTEXT(EntityMetadataText)
  ) HIDDEN;

-- The expression of a generated column cannot be altered in place, so
-- Metadata_Tokens is dropped and re-added with EntityMetadata_Tokens included.
-- The search index over it must be dropped first and recreated after.
DROP SEARCH INDEX EventGroupsByMetadata;

ALTER TABLE EventGroups
  DROP COLUMN Metadata_Tokens;

ALTER TABLE EventGroups
  ADD COLUMN Metadata_Tokens TOKENLIST AS (
    TOKENLIST_CONCAT([BrandName_Tokens, CampaignName_Tokens, EntityMetadata_Tokens])
  ) HIDDEN;

CREATE SEARCH INDEX EventGroupsByMetadata ON EventGroups(Metadata_Tokens);

-- Subtree scans: STARTS_WITH(EntityPath, prefix).
CREATE NULL_FILTERED INDEX EventGroupsByEntityPath
  ON EventGroups(DataProviderId, MeasurementConsumerId, EntityPath);

-- Direct-children scans. EntityType identifies a hierarchy level exactly, so a
-- level's children under a given path prefix are a contiguous key range.
CREATE NULL_FILTERED INDEX EventGroupsByEntityTypePath
  ON EventGroups(DataProviderId, MeasurementConsumerId, EntityType, EntityPath)
  STORING (DataAvailabilityStartTime, DataAvailabilityEndTime);

RUN BATCH;
